WITH store_daily AS ( SELECT ss.ss_store_sk, ss.ss_sold_date_sk, SUM(ss.ss_net_profit) AS daily_store_profit FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk WHERE i.i_category = 'Electronics' GROUP BY ss.ss_store_sk, ss.ss_sold_date_sk ), store_daily_ma AS ( SELECT sd.ss_store_sk, sd.ss_sold_date_sk, sd.daily_store_profit, AVG(sd.daily_store_profit) OVER (PARTITION BY sd.ss_store_sk ORDER BY sd.ss_sold_date_sk ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS three_day_moving_avg FROM store_daily sd ), web_daily AS ( SELECT ws.ws_warehouse_sk, ws.ws_sold_date_sk, SUM(ws.ws_net_profit) AS daily_warehouse_profit FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk WHERE i.i_category = 'Electronics' GROUP BY ws.ws_warehouse_sk, ws.ws_sold_date_sk ), web_daily_ma AS ( SELECT wd.ws_warehouse_sk, wd.ws_sold_date_sk, wd.daily_warehouse_profit, AVG(wd.daily_warehouse_profit) OVER (PARTITION BY wd.ws_warehouse_sk ORDER BY wd.ws_sold_date_sk ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS three_day_moving_avg FROM web_daily wd ) SELECT sd.ss_store_sk AS entity_id, sd.ss_sold_date_sk AS sale_date_sk, sd.daily_store_profit, sd.three_day_moving_avg, CASE WHEN sd.daily_store_profit > sd.three_day_moving_avg THEN 'Above Avg' ELSE 'Below Avg' END AS profit_trend, RANK() OVER (PARTITION BY sd.ss_sold_date_sk ORDER BY sd.daily_store_profit DESC) AS daily_rank, 'Store' AS channel, NULL AS location_name FROM store_daily_ma sd UNION ALL SELECT wd.ws_warehouse_sk AS entity_id, wd.ws_sold_date_sk AS sale_date_sk, wd.daily_warehouse_profit, wd.three_day_moving_avg, CASE WHEN wd.daily_warehouse_profit > wd.three_day_moving_avg THEN 'Above Avg' ELSE 'Below Avg' END AS profit_trend, RANK() OVER (PARTITION BY wd.ws_sold_date_sk ORDER BY wd.daily_warehouse_profit DESC) AS daily_rank, 'Web' AS channel, w.w_warehouse_name AS location_name FROM web_daily_ma wd JOIN warehouse w ON wd.ws_warehouse_sk = w.w_warehouse_sk ORDER BY sale_date_sk, daily_rank LIMIT 50
